ALTER TABLE `mr_wallet_sweep_order` ADD COLUMN `lease_owner` varchar(80) NOT NULL DEFAULT '' AFTER `last_error`, ADD COLUMN `lease_until` datetime DEFAULT NULL AFTER `lease_owner`, ADD COLUMN `next_retry_time` datetime DEFAULT NULL AFTER `lease_until`, ADD COLUMN `confirmed_time` datetime DEFAULT NULL AFTER `next_retry_time`, ADD KEY `idx_sweep_lease` (`status`,`next_retry_time`,`lease_until`,`id`);
ALTER TABLE `mr_wallet_withdraw_order` ADD COLUMN `lease_owner` varchar(80) NOT NULL DEFAULT '' AFTER `txid`, ADD COLUMN `lease_until` datetime DEFAULT NULL AFTER `lease_owner`, ADD COLUMN `retry_count` int unsigned NOT NULL DEFAULT 0 AFTER `lease_until`, ADD COLUMN `last_error` varchar(500) NOT NULL DEFAULT '' AFTER `retry_count`, ADD COLUMN `next_retry_time` datetime DEFAULT NULL AFTER `last_error`, ADD COLUMN `confirmed_time` datetime DEFAULT NULL AFTER `next_retry_time`;
